"""Build a dependency-free, escaped, static Pages dashboard."""
import html
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'site'
def e(value): return html.escape(str(value)) if value is not None else ''
def link(url): return f'<a href="{e(url)}" target="_blank" rel="noopener noreferrer">Official source ↗</a>'
def table(headers,rows):
    rows=list(rows)
    return '<div class="table-wrap"><table><thead><tr>'+''.join(f'<th>{e(x)}</th>' for x in headers)+'</tr></thead><tbody>'+(''.join('<tr>'+''.join(f'<td>{x}</td>' for x in row)+'</tr>' for row in rows) or f'<tr><td colspan="{len(headers)}">No verified entries available. See coverage and review flags.</td></tr>')+'</tbody></table></div>'
def main():
    d=json.loads((ROOT/'data/current.json').read_text()); OUT.mkdir(exist_ok=True)
    nav=[('index.html','Overview'),('matches.html','All matches'),('basketball.html','Basketball'),('ice-hockey.html','Ice hockey'),('baseball.html','Baseball'),('coverage.html','Sport coverage'),('markets.html','Markets & method'),('review.html','Flagged for Review')]
    def page(file,title,body):
        (OUT/file).write_text(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)} · OLBG Research</title><link rel="stylesheet" href="style.css"></head><body><aside><a class="brand" href="index.html">◈ OLBG<span>RESEARCH DESK</span></a><nav>{''.join(f'<a class="{"active" if f==file else ""}" href="{f}">{t}</a>' for f,t in nav)}</nav><small>Independent research project.<br>Not affiliated with OLBG.<br>18+ · No guaranteed outcomes.</small></aside><main><header><span class="eyebrow">SOURCE-FIRST SPORTS INTELLIGENCE</span><span class="badge">Partial coverage</span></header><h1>{e(title)}</h1><p class="muted">Snapshot: {e(d['generated'])} · All times UTC · <a href="data.json">Download data</a></p><div class="notice">Verification before prediction. Blank fields are intentional, not zero. No validated betting model or high-confidence recommendations are available.</div>{body}<footer>Official schedule verification does not verify a prediction. Updates run hourly when GitHub Actions succeeds. Data older than two hours should be treated as stale.</footer></main><script>const stamp=new Date({json.dumps(d['generated'])});if(Date.now()-stamp>7200000){{document.querySelector('.notice').prepend('STALE SNAPSHOT — ');}}</script></body></html>''')
    page('index.html','A clearer view of the schedule.',f'''<p class="intro">Upcoming fixtures, transparent evidence, and an honest account of what we can — and cannot — verify.</p><section class="metrics"><article><span>Verified fixture records</span><strong>{len(d['matches'])}</strong><small>Not a complete all-sport list</small></article><article><span>Schedule connectors</span><strong>3</strong><small>NBA · NHL · MLB only</small></article><article><span>Validated predictions</span><strong>0</strong><small>Evidence gate active</small></article></section><h2>Research workspace</h2><section class="cards"><a href="matches.html"><h3>Explore fixtures →</h3><p>Filter source-linked records by team or league.</p></a><a href="coverage.html"><h3>Inspect coverage →</h3><p>See supported leagues and unresolved sports.</p></a><a href="review.html"><h3>Review limitations →</h3><p>Missing inputs, unverified fields and scope gaps.</p></a></section><h2>Collection window</h2><p>{e(d['window_start'])} through {e(d['window_end'])}. Only upcoming fixtures returned by supported official feeds are shown. An empty table does not mean no matches exist.</p>''')
    def fixtures(sport=None):
        rows=[r for r in d['matches'] if sport is None or r['sport']==sport]
        return '<label class="search">Search teams or leagues <input id="search" placeholder="Search fixtures…" type="search"></label>'+table(['Sport / league','Match','Start UTC','Feed status','Winner','Confidence','Fair decimal line','Handicap','Total','Verification / missing fields','Source'],([e(r['sport']+' / '+r['league']),e(r['away']+' @ '+r['home']),e(r['start']),e(r['status']),'','','','','','Official fixture; betting fields, form and history unverified',link(r['source'])] for r in rows))+'''<script>document.getElementById('search').addEventListener('input',e=>document.querySelectorAll('tbody tr').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(e.target.value.toLowerCase())));</script>'''
    page('matches.html','Upcoming matches',fixtures())
    for file,sport in [('basketball.html','Basketball'),('ice-hockey.html','Ice hockey'),('baseball.html','Baseball')]: page(file,sport,fixtures(sport))
    page('coverage.html','Sport coverage', '<p>Three league-level adapters are not comprehensive sport coverage. Reference links below identify source candidates, not verified fixtures.</p>'+table(['Sport','League','Collection status','Source'],([e(r['sport']),e(r['league']),e(r['status']),link(r['source'])] for r in d['coverage'])))
    page('markets.html','Markets & methodology','''<h2>Do not confuse facts with model estimates</h2><p>Fixtures are extracted directly from official league JSON feeds. Missing fields are blank. No bookmaker lines, community voting percentages or scraped opinions are presented as our own probabilities.</p><h2>Prediction release gate</h2><ol><li>Verify participants, start time, venue, current form and recent results from dated official records.</li><li>Train and out-of-time validate a sport-specific model; publish training window, inputs, calibration and uncertainty.</li><li>Originate fair prices from calibrated probabilities. These are model estimates, never official facts.</li><li>Evaluate market settlement rules, handicap and total distributions; validate each market separately.</li><li>Assign low, medium or high confidence only against documented validation thresholds, not a subjective label.</li><li>Release high-confidence prose only when supported by linked match-specific evidence, with an explicit selection and at least 30 words. Do not manufacture player news or form.</li></ol><p>These gates are not satisfied. No trained model is included, and all picks remain withheld.</p>'''+table(['Market','Availability','Official fixture evidence'],[[m,'Unverified — no model or market-specific evidence',link('https://www.nba.com/games')] for m in ['Match winner / moneyline','Handicap / spread','Match total','Period / set markets','Player props','Other sport-specific markets']]))
    flags=[('Pages publishing permissions','Artifact deployment works, but the repository remains configured for legacy branch builds. Main-branch pushes may briefly trigger competing publication; scheduled Actions republish the dashboard. Pages settings write is denied.','https://github.com/buffedlizard55-lab/OLBG3/actions'),('Coverage incomplete','Only NBA, NHL and MLB adapters implemented. Other leagues, women’s competitions and eligible sports remain incomplete.','https://www.olbg.com/betting-tips'),('OLBG discovery is not official verification','OLBG community tips and popular-event lists are neither a complete fixture feed nor calibrated win probabilities.','https://www.olbg.com/betting-tips'),('No validated model','Fair lines, selections, confidence, current form, history and predictions intentionally blank. Official schedules cannot establish these.','https://www.nba.com/games'),('Schedule horizon','Seven-day UTC window; NHL may return fewer days. Postponements and source delays can affect availability.','https://api-web.nhle.com/v1/schedule/now'),('Excluded sports','Explicitly excluded: '+', '.join(d['excluded'])+'. Football interpreted broadly, including Gaelic football.','https://www.olbg.com/betting-tips')]
    page('review.html','Flagged for Review','<p>These limitations are published openly. They do not turn missing information into verified information.</p>'+table(['Flag','Finding','Source / review reference'],([e(a),e(b),link(c)] for a,b,c in flags))+ '<h2>Connector audit</h2>'+table(['Sport','Latest result','Source'],([e(r['sport']),e(r['status']),link(r['source'])] for r in d['coverage'])))
    (OUT/'data.json').write_text(json.dumps(d,indent=2))
    (OUT/'style.css').write_text('''*{box-sizing:border-box}body{margin:0;background:#f5f7fa;color:#172b3a;font:15px/1.6 system-ui,sans-serif}aside{position:fixed;width:240px;height:100vh;background:#112c38;color:#b4cbd4;padding:32px 22px;display:flex;flex-direction:column}.brand{font-size:26px;color:white;text-decoration:none;font-weight:750}.brand span{display:block;font-size:10px;letter-spacing:3px;color:#67dac0;margin:8px 0 35px}nav a{display:block;padding:12px 14px;margin:4px 0;text-decoration:none;color:#c4d6df;border-radius:7px}nav a:hover,nav a.active{background:#234552;color:#7aefce}aside small{margin-top:auto;font-size:11px}main{margin-left:240px;padding:36px 42px;max-width:1800px}header{display:flex;justify-content:space-between;gap:15px;align-items:center}.eyebrow{letter-spacing:2px;font-size:10px;font-weight:700;color:#52717e}.badge{padding:5px 12px;background:#fff1cd;color:#745100;border-radius:30px;font-size:12px}h1{font-size:clamp(30px,4vw,46px);letter-spacing:-1.5px;margin:26px 0 5px;line-height:1.2}h2{font-size:21px;margin-top:34px}.muted,footer{color:#647784;font-size:12px}a{color:#087d73}.notice{padding:15px 19px;border-left:3px solid #d9aa47;background:#fff8e8;margin:24px 0;color:#715a27;font-size:13px}.intro{max-width:700px;font-size:18px;color:#59717c}.metrics,.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin:26px 0}.metrics article,.cards a{background:white;border:1px solid #dce5eb;padding:24px;border-radius:10px}.metrics span,.metrics small{display:block;color:#607785;font-size:12px}.metrics strong{display:block;font-size:42px;color:#0c7b6d;margin:8px 0}.cards a{text-decoration:none;color:inherit}.cards a:hover{border-color:#0b9482}.cards p{font-size:13px;color:#607785}.table-wrap{overflow:auto;border:1px solid #dce5eb;border-radius:9px;background:white;margin:20px 0}table{width:100%;border-collapse:collapse;text-align:left;font-size:13px}th{background:#edf3f5;font-size:11px;text-transform:uppercase;letter-spacing:.5px;white-space:nowrap}td,th{padding:16px;border-bottom:1px solid #e5ecf0;vertical-align:top}td{min-width:110px}tr:last-child td{border-bottom:0}tr:hover td{background:#f5fbfa}.search{display:block;font-size:12px;font-weight:600}input{display:block;margin-top:7px;width:min(100%,480px);padding:12px;border:1px solid #cad8df;border-radius:7px;font:inherit}footer{margin-top:45px;padding-top:20px;border-top:1px solid #dce5eb}li{margin:12px 0}@media(max-width:850px){aside{position:static;width:auto;height:auto;padding:18px}aside small{display:none}.brand span{margin:0}nav{display:flex;flex-wrap:wrap;margin-top:12px}nav a{padding:6px 10px;font-size:12px}main{margin:0;padding:24px 18px}.metrics,.cards{grid-template-columns:1fr}.metrics article{padding:18px}.eyebrow{font-size:8px}}''')
if __name__=='__main__': main()
